import pyomo.environ as pyo

DATA = {
    "num_dc": 7,
    "num_store": 6,
    "open_cost": {
        1: 151000, 2: 192000, 3: 114000, 4: 171000,
        5: 160000, 6: 120000, 7: 182000,
    },
    "transport_cost": {
        (1, 1): 3, (1, 2): 3, (1, 3): 5, (1, 4): 4, (1, 5): 3, (1, 6): 5,
        (2, 1): 2, (2, 2): 4, (2, 3): 2, (2, 4): 4, (2, 5): 5, (2, 6): 1,
        (3, 1): 4, (3, 2): 2, (3, 3): 5, (3, 4): 4, (3, 5): 1, (3, 6): 1,
        (4, 1): 3, (4, 2): 3, (4, 3): 2, (4, 4): 4, (4, 5): 4, (4, 6): 3,
        (5, 1): 4, (5, 2): 4, (5, 3): 1, (5, 4): 3, (5, 5): 5, (5, 6): 3,
        (6, 1): 5, (6, 2): 1, (6, 3): 2, (6, 4): 4, (6, 5): 1, (6, 6): 4,
        (7, 1): 2, (7, 2): 2, (7, 3): 1, (7, 4): 2, (7, 5): 5, (7, 6): 2,
    },
    "demand": {
        1: 739, 2: 491, 3: 766, 4: 854, 5: 827, 6: 908,
    },
    "capacity": {
        1: 1575, 2: 834, 3: 1005, 4: 1904,
        5: 1825, 6: 1821, 7: 1365,
    },
}


def build_model(data=None):
    d = data or DATA

    m = pyo.ConcreteModel()

    m.I = pyo.RangeSet(1, d["num_dc"])
    m.J = pyo.RangeSet(1, d["num_store"])

    # y[i] = 1 if distribution center i is opened
    m.y = pyo.Var(m.I, within=pyo.Binary)

    # x[i,j] = units shipped from DC i to store j (nonnegative integers)
    m.x = pyo.Var(m.I, m.J, within=pyo.NonNegativeIntegers)

    # Objective: minimise opening costs + transportation costs
    def obj_rule(mm):
        return (
            sum(d["open_cost"][i] * mm.y[i] for i in mm.I)
            + sum(d["transport_cost"][(i, j)] * mm.x[i, j]
                  for i in mm.I for j in mm.J)
        )

    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Demand satisfaction: sum_i x[i,j] == d_j for each store j
    def demand_rule(mm, j):
        return sum(mm.x[i, j] for i in mm.I) == d["demand"][j]

    m.demand_con = pyo.Constraint(m.J, rule=demand_rule)

    # Capacity & linking: sum_j x[i,j] <= cap_i * y[i]  (ship only if opened)
    def capacity_rule(mm, i):
        return sum(mm.x[i, j] for j in mm.J) <= d["capacity"][i] * mm.y[i]

    m.capacity_con = pyo.Constraint(m.I, rule=capacity_rule)

    return m


